package db

import (
	"context"
	"crypto/subtle"
	"database/sql"
	"errors"
	"fmt"
)

// Pending instance-admin verification tokens (import flow). Shared with Node:
// tokens are generated by either process and consumed by Node's
// create-user-with-config, so they live in SQLite rather than process memory.

// SetPendingToken stores (or replaces) the pending token for kind+username.
func SetPendingToken(ctx context.Context, database *sql.DB, kind, username, token string) error {
	_, err := database.ExecContext(ctx,
		"INSERT OR REPLACE INTO pending_auth_tokens (kind, username, token, created_at) VALUES (?, ?, ?, CURRENT_TIMESTAMP)",
		kind, username, token)
	if err != nil {
		return fmt.Errorf("set pending token: %w", err)
	}
	return nil
}

// GetPendingToken returns the pending token for kind+username, or nil.
func GetPendingToken(ctx context.Context, database *sql.DB, kind, username string) (*string, error) {
	row := database.QueryRowContext(ctx,
		"SELECT token FROM pending_auth_tokens WHERE kind = ? AND username = ? LIMIT 1", kind, username)

	var val string
	err := row.Scan(&val)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("get pending token: %w", err)
	}
	return &val, nil
}

// DeletePendingToken removes the pending token for kind+username.
func DeletePendingToken(ctx context.Context, database *sql.DB, kind, username string) error {
	_, err := database.ExecContext(ctx,
		"DELETE FROM pending_auth_tokens WHERE kind = ? AND username = ?", kind, username)
	if err != nil {
		return fmt.Errorf("delete pending token: %w", err)
	}
	return nil
}

// PendingTokenMatches reports whether token is the pending token stored for
// kind+username, WITHOUT consuming it. Callers that grant a privilege use
// this to check the code up front and ConsumePendingToken only after the
// privilege actually exists: consuming first means a failed insert burns a
// code that took a trip through the server logs to obtain.
func PendingTokenMatches(ctx context.Context, database *sql.DB, kind, username, token string) (bool, error) {
	if token == "" {
		return false, nil
	}
	stored, err := GetPendingToken(ctx, database, kind, username)
	if err != nil || stored == nil {
		return false, err
	}
	return subtle.ConstantTimeCompare([]byte(*stored), []byte(token)) == 1, nil
}

// ConsumePendingToken atomically verifies and clears a pending token: the
// DELETE matches on the token value itself, so exactly one concurrent caller
// can win, and a concurrently regenerated token is never erased by mistake.
// Returns true if this call consumed the matching token.
func ConsumePendingToken(ctx context.Context, database *sql.DB, kind, username, token string) (bool, error) {
	res, err := database.ExecContext(ctx,
		"DELETE FROM pending_auth_tokens WHERE kind = ? AND username = ? AND token = ?",
		kind, username, token)
	if err != nil {
		return false, fmt.Errorf("consume pending token: %w", err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return false, fmt.Errorf("consume pending token: %w", err)
	}
	return n == 1, nil
}
